-- Timestamps are now maintained by MySQL instead of the application:
-- every updatedAt column defaults to the current time and changes on every update.
-- Also removes the bookkeeping table of the previous migration tool.

ALTER TABLE `roles` MODIFY `updatedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3);
ALTER TABLE `users` MODIFY `updatedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3);
